  add("plate-darts", "Pressure plate and darts", "pressure", "physical", [2, 4], "hidden", { trig: ["step", "A flagstone in the way sinks under a person's weight."], how: "Weight on the plate looses darts from holes along both walls, across the width of the passage.", seen: "One flagstone sunk a finger's breadth, and rows of dark holes in both walls.", harm: ["piercing", "dodge"], alt: ["The darts are drugged: whoever is hit is slow and drowsy for an hour.", "The darts are blunt; the plate also rings a bell somewhere deeper in."], signs: ["One flagstone sits a hair lower than the rest.", "Tiny holes in the walls at knee and chest height.", "Snapped dart shafts on the floor, some of them old."], detect: "perceive", disarm: ["mechanism", "Wedge the plate so it cannot sink, or plug the holes."], bypass: [["Step over the plate once it is found."], ["Crawl beneath the line of the darts.", "balance"]], reset: "auto", props: ["trap-plate", "trap-darts"], area: [1, 3], noise: 1 });
