  add("loose-stones", "Loose stones", "pressure", "physical", [1, 1], "partial", { trig: ["step", "Loose, rounded stones laid across the way."], how: "They roll and clatter loudly underfoot; it is an alarm, not a weapon.", seen: "A carpet of rounded stones across the passage.", harm: null, alt: ["The clatter carries: whatever lives deeper in knows someone is coming.", "Someone falls and drops their light, which rolls away into the dark."], signs: ["The stones are too round and too many to have fallen here.", "There is a quiet path along one wall that has been used."], detect: "perceive", disarm: ["stealth", "Clear a quiet way stone by stone (slow)."], bypass: [["Walk the quiet edge along the wall.", "stealth"], ["Lay cloaks over the stones."]], reset: "none", props: ["pebbles"], area: [1, 3], noise: 1 });
  add("cave-in", "Triggered cave-in", "pressure", "physical", [2, 4], "hidden", { trig: ["touch", "An old prop holds up a mass of loose rock; a tripline or a careless shoulder moves it."], how: "The prop falls and the roof comes down across the passage.", seen: "A shower of grit, then the roof coming down.", harm: ["bludgeoning", "dodge"], alt: ["The fall seals the way behind them: digging out takes hours.", "The fall lands between them and splits the party."], signs: ["A timber prop, newer than the passage.", "Cracks across the roof; small stones on the floor beneath them.", "Old rubble heaped to the sides, as if this has fallen before."], detect: "perceive", disarm: ["mechanism", "Shore up the prop and cut the line."], bypass: [["Pass without touching the prop or the line.", "balance"]], reset: "none", props: ["rubble-stone"], area: [1, 3], sep: 1, noise: 1 });
